local Tab = Window:NewTab("Units")
local Section = Tab:NewSection("all Units")



Section:NewButton("Speakerman (100)", "ButtonInfo", function()
 local args = {
    [1] = "Normal_SpeakerMan",
    [2] =
CFrame.new(game.Players.LocalPlayer.Character.Head.Position)
}

game:GetService("ReplicatedStorage"):WaitForChild("RemoteEvents"):WaitForChild("SpawnUnits"):FireServer(unpack(args))
end)


